// Plain own host process. The /lab routes are synthetic test control, never product endpoints.
import {HostStore,ConversationRuntime,HostError} from '@dexter/hub';
import {CapabilityGateway,SyntheticCredentialBroker} from '@dexter/gateway';
import {createHostApp} from '@dexter/hub/http';
import {serve} from '@hono/node-server';
import {Agenda} from '@dexter/agenda';
import {WorkspaceDriver} from '../../packages/cli/dist/workspace-driver.js';
import {HarnessOperationSurface,HARNESS_OPERATION_DESTINATION} from '../../packages/cli/dist/harness-operation-surface.js';
import {BotWorkspaceTools} from '../../packages/cli/dist/bot-workspace-tools.js';
const args=JSON.parse(process.argv[2]);
const store=new HostStore({dataDir:args.dataDir}),workspace=new BotWorkspaceTools({dataDir:args.dataDir});
const gateway=new CapabilityGateway({store,broker:new SyntheticCredentialBroker(),adapter:{execute:async()=>({synthetic:true})}});
const selection={engine:'claude',model:'r3-model',reasoningEffort:'high',speed:null};
const bot=args.botId?store.getBot(args.botId):store.createBot({name:'R3 synthetic',profileId:'r3-synthetic',engine:'claude',defaultSelection:selection}),thread=args.threadId?store.getThread(args.threadId):store.createThread(bot.id);
let runtime,ownerCalls=0;
const catalog=async()=>[{id:'claude',available:true,models:[{id:'r3-model',reasoningEfforts:['high'],speeds:[]}],defaultModel:'r3-model',reasoningEfforts:['high'],speeds:[]}];
const surface=new HarnessOperationSurface({store,base:gateway,catalog,runtime:()=>runtime,skills:()=>({}),effectiveSkills:()=>[],workspace:()=>workspace});
const driver=new WorkspaceDriver('claude',store,args.dataDir,{command:args.engine,mcp:{gateway:surface,wrapperPath:args.wrapper,bridgeLimits:{requestTimeoutMs:args.deadline}}});
runtime=new ConversationRuntime({store,drivers:[driver],engineCatalog:catalog,ownerActionContinuation:async action=>{ownerCalls++;if(args.broken)throw new HostError('not_found','synthetic private port message');return surface.continueOwnerAction(action);}});
const agenda=new Agenda(store),app=createHostApp(store,{runtime});
await runtime.recoverOwnerActions();
app.get('/lab/state',c=>c.json({actions:store.listActions(),turns:store.listTurns(thread.id),messages:store.listMessages(thread.id),unsettled:store.hasUnsettledThreadActions(thread.id),ownerCalls}));
app.post('/lab/agenda-create',async c=>c.json(agenda.createAutomation({hostId:store.hostId,clientRequestId:'r3-agenda-create',expectedRevision:0,botId:bot.id,threadId:thread.id,title:'R3',content:'synthetic next occurrence',when:{kind:'interval',everyMs:60000,firstAt:store.now()+3600000}})));
app.post('/lab/agenda-run',async c=>{try{return c.json(agenda.runAutomation((await c.req.json()).id,{hostId:store.hostId,clientRequestId:'r3-agenda-run-'+store.now(),expectedRevision:1}));}catch(error){return c.json({error:error.code},409);}});
app.post('/lab/change-authority',async c=>{const mode=(await c.req.json()).kind;if(mode==='grant')store.setGrant({botId:bot.id,tool:'dexter.harness.terminal.run',destination:HARNESS_OPERATION_DESTINATION,policy:'deny'});else store.patchBot(bot.id,{expectedRevision:store.getBot(bot.id).revision,name:'R3 revised'});return c.json({changed:true});});
const server=serve({fetch:app.fetch,hostname:'127.0.0.1',port:0});await new Promise(r=>server.once('listening',r));
process.send({port:server.address().port,botId:bot.id,threadId:thread.id,hostId:store.hostId});
let stopping=false;
const stop=async()=>{if(stopping)return;stopping=true;store.stopApprovedExecutions();surface.stopAdmission();gateway.stopAdmission();await runtime.shutdown({closeStore:false,graceMs:3000});await surface.close();await workspace.close();await new Promise(r=>server.close(r));agenda.close();gateway.close();store.close();process.exit(0);};
process.on('message',message=>{if(message==='shutdown')void stop();});
process.on('SIGTERM',()=>void stop());
